css:
.fxt-flap {
  --fxt-flap-bg: oklch(0.205 0.008 70);
  --fxt-flap-ink: oklch(0.95 0.022 92);
  --fxt-flap-accent: oklch(0.85 0.15 84);
  --fxt-flap-face: oklch(0.275 0.006 70);
  --fxt-flap-ok: oklch(0.8 0.16 150);
  --fxt-flap-warn: oklch(0.75 0.16 52);
  --fxt-flap-bad: oklch(0.67 0.2 26);
  --fxt-flap-dim: color-mix(in oklch, var(--fxt-flap-ink) 50%, var(--fxt-flap-bg));
  --fxt-flap-line: color-mix(in oklch, var(--fxt-flap-ink) 11%, transparent);
  --fxt-flap-pad: 16px;
  --fxt-flap-gap: 3px;
  container-type: inline-size;
  box-sizing: border-box;
  inline-size: 100%;
  display: grid;
  grid-template-columns: auto 1fr auto;
  grid-template-areas:
    "head head head"
    "time .    plat"
    "dest dest dest"
    "via  via  via"
    "next next next"
    "foot foot foot";
  row-gap: 11px;
  padding: var(--fxt-flap-pad);
  border-radius: 14px;
  border: 1px solid var(--fxt-flap-line);
  background:
    radial-gradient(120% 70% at 50% 0%, color-mix(in oklch, var(--fxt-flap-ink) 7%, transparent), transparent 62%),
    var(--fxt-flap-bg);
  color: var(--fxt-flap-ink);
  font-family: system-ui, sans-serif;

  & .fxt-flap-head {
    grid-area: head;
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 12px;
  }
  & .fxt-flap-logo {
    inline-size: 18px;
    block-size: 18px;
    fill: none;
    stroke: var(--fxt-flap-accent);
    stroke-width: 1.6;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxt-flap-logo circle { fill: var(--fxt-flap-accent); stroke: none; }
  & .fxt-flap-brand { font-weight: 650; letter-spacing: .005em; }
  & .fxt-flap-board {
    margin-inline-start: auto;
    padding: 3px 8px;
    border: 1px solid var(--fxt-flap-line);
    border-radius: 99px;
    font-size: 9.5px;
    font-weight: 700;
    letter-spacing: .16em;
    text-transform: uppercase;
    color: var(--fxt-flap-accent);
  }

  & .fxt-flap-field { display: grid; gap: 5px; align-content: start; }
  & .fxt-flap-time { grid-area: time; }
  & .fxt-flap-plat { grid-area: plat; justify-items: end; }
  & .fxt-flap-dest { grid-area: dest; }
  & .fxt-flap-lbl {
    font-size: 9.5px;
    font-weight: 650;
    letter-spacing: .16em;
    text-transform: uppercase;
    color: var(--fxt-flap-dim);
  }

  & .fxt-flap-cells {
    --cw: clamp(15px, calc((100cqi - 2 * var(--fxt-flap-pad) - 10 * var(--fxt-flap-gap)) / 11), 34px);
    --ch: calc(var(--cw) * 1.42);
    display: flex;
    gap: var(--fxt-flap-gap);
  }
  & .fxt-flap-c {
    position: relative;
    inline-size: var(--cw);
    block-size: var(--ch);
    perspective: calc(var(--ch) * 5);
    border-radius: 3px;
    font: 650 calc(var(--ch) * .64)/1 system-ui, sans-serif;
    font-variant-numeric: tabular-nums;
    color: var(--fxt-flap-ink);
    box-shadow: 0 2px 5px oklch(0 0 0 / .45), 0 1px 0 color-mix(in oklch, var(--fxt-flap-ink) 6%, transparent);
  }
  & .fxt-flap-time .fxt-flap-c { color: var(--fxt-flap-accent); }
  & .fxt-flap-c::after {
    content: "";
    position: absolute;
    inset-inline: 0;
    top: calc(50% - .5px);
    block-size: 1px;
    background: oklch(0 0 0 / .7);
    z-index: 3;
  }
  & .fxt-flap-c::before {
    content: "";
    position: absolute;
    top: calc(50% - 2px);
    inset-inline: -1px;
    block-size: 4px;
    border-inline: 2px solid var(--fxt-flap-bg);
    z-index: 4;
  }
  & .fxt-flap-h {
    position: absolute;
    inset-inline: 0;
    block-size: 50%;
    overflow: hidden;
    backface-visibility: hidden;
  }
  & .fxt-flap-h b {
    display: grid;
    place-items: center;
    block-size: 200%;
    font-weight: inherit;
  }
  & .fxt-flap-st, & .fxt-flap-ft {
    top: 0;
    border-radius: 3px 3px 0 0;
    background: linear-gradient(color-mix(in oklch, var(--fxt-flap-face), white 5%), var(--fxt-flap-face));
  }
  & .fxt-flap-sb, & .fxt-flap-fb {
    bottom: 0;
    border-radius: 0 0 3px 3px;
    background: linear-gradient(var(--fxt-flap-face), color-mix(in oklch, var(--fxt-flap-face), black 18%));
  }
  & .fxt-flap-sb b, & .fxt-flap-fb b { translate: 0 -50%; }
  & .fxt-flap-ft { transform-origin: 50% 100%; z-index: 2; }
  & .fxt-flap-fb { transform-origin: 50% 0; transform: rotateX(90deg); z-index: 2; }

  & .fxt-flap-via {
    grid-area: via;
    margin: 0;
    min-block-size: 2lh;
    font-size: 12.5px;
    line-height: 1.4;
    color: color-mix(in oklch, var(--fxt-flap-ink) 76%, var(--fxt-flap-bg));
    text-wrap: pretty;
  }

  & .fxt-flap-next {
    grid-area: next;
    display: grid;
    margin: 0;
    padding: 0;
    list-style: none;
    font: 500 11px ui-monospace, Menlo, monospace;
    color: var(--fxt-flap-dim);
  }
  & .fxt-flap-next li {
    display: grid;
    grid-template-columns: 5.5ch 1fr auto;
    align-items: baseline;
    gap: 10px;
    padding-block: 5px;
    border-top: 1px dashed var(--fxt-flap-line);
    transition: opacity .5s cubic-bezier(.2,.7,.2,1), translate .7s linear(0, 0.0471, 0.1663, 0.327, 0.5032, 0.675, 0.8281, 0.9541, 1.0493, 1.1136, 1.15, 1.1628, 1.1575, 1.1396, 1.1142, 1.0857, 1.0574, 1.0318, 1.0105, 0.9941, 0.9828, 0.9762, 0.9736, 0.974, 0.9767, 0.9807, 0.9853, 0.9899, 0.9942, 0.9978, 1.0006, 1.0026, 1.0037, 1.0043, 1.0043, 1.0039, 1.0033, 1.0025, 1.0018, 1.0011, 1);
    transition-delay: calc(var(--i, 0) * 80ms + 320ms);
    @starting-style {
      opacity: 0;
      translate: 0 5px;
    }
  }
  & .fxt-flap-next time { color: color-mix(in oklch, var(--fxt-flap-accent) 72%, var(--fxt-flap-dim)); font-variant-numeric: tabular-nums; }
  & .fxt-flap-next span {
    overflow: hidden;
    font: 500 12px system-ui, sans-serif;
    color: color-mix(in oklch, var(--fxt-flap-ink) 70%, var(--fxt-flap-bg));
    white-space: nowrap;
    text-overflow: ellipsis;
  }
  & .fxt-flap-next b { font-weight: 600; font-variant-numeric: tabular-nums; }

  & .fxt-flap-foot {
    grid-area: foot;
    display: grid;
    grid-template-columns: auto 1fr auto auto;
    align-items: center;
    gap: 10px;
    padding-top: 11px;
    border-top: 1px solid var(--fxt-flap-line);
  }
  & .fxt-flap-btn {
    display: grid;
    place-items: center;
    inline-size: 30px;
    block-size: 30px;
    padding: 0;
    border: 1px solid var(--fxt-flap-line);
    border-radius: 8px;
    background: color-mix(in oklch, var(--fxt-flap-ink) 5%, transparent);
    color: var(--fxt-flap-ink);
    cursor: pointer;
    transition: background-color .2s cubic-bezier(.2,.7,.2,1), translate .35s linear(0, 0.0471, 0.1663, 0.327, 0.5032, 0.675, 0.8281, 0.9541, 1.0493, 1.1136, 1.15, 1.1628, 1.1575, 1.1396, 1.1142, 1.0857, 1.0574, 1.0318, 1.0105, 0.9941, 0.9828, 0.9762, 0.9736, 0.974, 0.9767, 0.9807, 0.9853, 0.9899, 0.9942, 0.9978, 1.0006, 1.0026, 1.0037, 1.0043, 1.0043, 1.0039, 1.0033, 1.0025, 1.0018, 1.0011, 1);
  }
  & .fxt-flap-btn svg {
    inline-size: 16px;
    block-size: 16px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.8;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxt-flap-btn:hover { background: color-mix(in oklch, var(--fxt-flap-ink) 13%, transparent); }
  & .fxt-flap-btn:active { translate: 0 1px; }
  & .fxt-flap-btn:focus-visible { outline: 2px solid var(--fxt-flap-accent); outline-offset: 2px; }
  & .fxt-flap-btn[data-dir="1"]:hover svg { translate: 1px 0; }
  & .fxt-flap-btn[data-dir="-1"]:hover svg { translate: -1px 0; }

  & .fxt-flap-status {
    --c: var(--fxt-flap-ok);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    min-inline-size: 0;
    font-size: 12px;
    font-weight: 650;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  & .fxt-flap-status i {
    position: relative;
    flex: none;
    inline-size: 8px;
    block-size: 8px;
    border-radius: 50%;
    background: var(--c);
    box-shadow: 0 0 0 3px color-mix(in oklch, var(--c) 22%, transparent);
  }
  & .fxt-flap-status[data-state="board"] { --c: var(--fxt-flap-accent); }
  & .fxt-flap-status[data-state="late"] { --c: var(--fxt-flap-warn); }
  & .fxt-flap-status[data-state="cancel"] { --c: var(--fxt-flap-bad); color: var(--fxt-flap-bad); }
  & .fxt-flap-status[data-state="board"] i::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: 50%;
    background: var(--c);
    animation: fxt-flap-ping 1.6s cubic-bezier(.2,.6,.3,1) infinite;
  }
  & .fxt-flap-count {
    font-size: 11px;
    color: var(--fxt-flap-dim);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }
  & .fxt-flap-count b { color: var(--fxt-flap-ink); font-weight: 650; }
  & .fxt-flap-sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}
.fxt-flap { position: relative; }

@keyframes fxt-flap-ping {
  from { transform: scale(1); opacity: .75; }
  to { transform: scale(3.2); opacity: 0; }
}

@container (min-width: 520px) {
  .fxt-flap .fxt-flap-cells { --cw: clamp(15px, calc((100cqi - 2 * var(--fxt-flap-pad) - 10 * var(--fxt-flap-gap)) / 11), 44px); }
  .fxt-flap .fxt-flap-via { font-size: 14px; }
  .fxt-flap .fxt-flap-head { font-size: 13px; }
}
@container (max-width: 250px) {
  .fxt-flap .fxt-flap-board { display: none; }
  .fxt-flap .fxt-flap-count { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .fxt-flap .fxt-flap-status i::after { animation: none; opacity: 0; }
  .fxt-flap .fxt-flap-btn, .fxt-flap .fxt-flap-btn svg, .fxt-flap .fxt-flap-next li { transition: none; }
}

js:
const DRUM = ' ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789:.-';
const DEPS = [
  { time: '14:05', dest: 'HALVERSTON', plat: '4', via: 'Calling at Brennick and Low Meadow.', status: 'On time', state: 'ok' },
  { time: '14:12', dest: 'VANTRY QUAY', plat: '7', via: 'Fast service. First stop Eldermoor, then Vantry Quay.', status: 'Boarding', state: 'board' },
  { time: '14:20', dest: 'ELDERMOOR', plat: '2', via: 'Calling at Cask Hollow and Fennick Road.', status: 'Delayed, exp 14:24', state: 'late' },
  { time: '14:31', dest: 'CORRAN BAY', plat: '11', via: 'Calling at Saltmere, Pell Cross and Orrin Sands.', status: 'On time', state: 'ok' },
  { time: '14:46', dest: 'CASK HOLLOW', plat: '5', via: 'Stopping service, all stations. Front four coaches only.', status: 'On time', state: 'ok' },
  { time: '15:02', dest: 'BRENNICK', plat: '--', via: 'Replacement coach departs from the station forecourt.', status: 'Cancelled', state: 'cancel' }
];
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const OFFSET = { time: 0, dest: 70, plat: 150 };
const HALVES = '<span class="fxt-flap-h fxt-flap-st"><b></b></span><span class="fxt-flap-h fxt-flap-sb"><b></b></span>' +
  '<span class="fxt-flap-h fxt-flap-ft"><b></b></span><span class="fxt-flap-h fxt-flap-fb"><b></b></span>';
const via = root.querySelector('.fxt-flap-via');
const stat = root.querySelector('.fxt-flap-status');
const statT = root.querySelector('.fxt-flap-status-t');
const count = root.querySelector('.fxt-flap-count b');
const sr = root.querySelector('.fxt-flap-sr');
const nextList = root.querySelector('.fxt-flap-next');
const fields = {}, cells = [];

root.querySelectorAll('.fxt-flap-cells').forEach((box) => {
  const name = box.dataset.field, len = +box.dataset.len, list = [];
  box.textContent = '';
  for (let i = 0; i < len; i++) {
    const el = document.createElement('span');
    el.className = 'fxt-flap-c';
    el.innerHTML = HALVES;
    box.appendChild(el);
    const [st, sb, ft, fb] = el.children;
    const c = { st: st.firstChild, sb: sb.firstChild, ftB: ft.firstChild, fbB: fb.firstChild, ft, fb,
      cur: 0, next: 0, target: 0, t: 0, wait: 0, dur: 60, last: false, delay: (OFFSET[name] || 0) + i * 42 };
    list.push(c);
    cells.push(c);
  }
  fields[name] = list;
});

const put = (b, k) => { b.textContent = DRUM[k]; };
const idxOf = (ch) => Math.max(0, DRUM.indexOf(ch));
const layout = (d) => ({ time: d.time, dest: d.dest.padEnd(11, ' ').slice(0, 11), plat: d.plat.padStart(2, ' ') });
const titled = (s) => s.toLowerCase().replace(/\b\w/g, (m) => m.toUpperCase());

function setInstant(dep) {
  const L = layout(dep);
  for (const name in fields) fields[name].forEach((c, i) => {
    const k = idxOf(L[name][i] || ' ');
    c.cur = c.next = c.target = k; c.t = 0; c.wait = 0;
    put(c.st, k); put(c.sb, k); put(c.ftB, k); put(c.fbB, k);
    c.ft.style.transform = c.fb.style.transform = c.ft.style.filter = c.fb.style.filter = '';
  });
}

let idx = 0, onScreen = false, raf = 0, last = 0, autoT = 0, hover = false, focusIn = false;

function info(dep, quiet) {
  stat.dataset.state = dep.state;
  statT.textContent = dep.status;
  via.textContent = dep.via;
  count.textContent = idx + 1;
  nextList.textContent = '';
  for (let k = 1; k <= 2; k++) {
    const d = DEPS[idx + k];
    if (!d) break;
    const li = document.createElement('li');
    li.style.setProperty('--i', k - 1);
    li.innerHTML = '<time></time><span></span><b></b>';
    li.children[0].textContent = d.time;
    li.children[1].textContent = titled(d.dest) + (d.state === 'cancel' ? ' (cancelled)' : '');
    li.children[2].textContent = d.plat === '--' ? 'Pl. \u2013' : 'Pl. ' + d.plat;
    nextList.appendChild(li);
  }
  if (!nextList.children.length) {
    const li = document.createElement('li');
    li.innerHTML = '<time>--:--</time><span>Last departure of the afternoon</span><b></b>';
    nextList.appendChild(li);
  }
  if (quiet) return;
  sr.textContent = dep.time + ' to ' + titled(dep.dest) + ', platform ' + (dep.plat === '--' ? 'not assigned' : dep.plat) + '. ' + dep.status + '.';
  if (!reduce && via.animate) {
    via.animate([{ clipPath: 'inset(0 100% 0 0)', opacity: .3 }, { clipPath: 'inset(0 0 0 0)', opacity: 1 }],
      { duration: 900, delay: 240, easing: 'cubic-bezier(.22,.8,.18,1)', fill: 'backwards' });
  }
}

function go(n) {
  idx = (n + DEPS.length) % DEPS.length;
  const dep = DEPS[idx];
  clearTimeout(autoT);
  info(dep);
  if (reduce) {
    setInstant(dep);
    root.querySelectorAll('.fxt-flap-cells').forEach((b) => b.animate && b.animate([{ opacity: .35 }, { opacity: 1 }], { duration: 240, easing: 'cubic-bezier(.2,.7,.3,1)' }));
    return;
  }
  const L = layout(dep);
  for (const name in fields) fields[name].forEach((c, i) => {
    const k = idxOf(L[name][i] || ' ');
    if (k === c.target) return;
    c.target = k;
    if (c.t === 0) c.wait = c.delay + Math.random() * 24;
  });
  wake();
}

// A flip is 0..180deg of one leaf. Gravity: the angle grows with t^2.
// The last flip of a run lands and bounces once before settling.
function angle(c) {
  const t = c.t;
  if (!c.last) return 180 * t * t;
  if (t < .72) { const p = t / .72; return 180 * p * p; }
  const p = (t - .72) / .28;
  return 180 - 16 * Math.sin(Math.PI * p) * (1 - p * .4);
}
function pose(c) {
  const a = angle(c);
  if (a <= 90) {
    c.ft.style.transform = 'rotateX(' + (-a).toFixed(2) + 'deg)';
    c.ft.style.filter = 'brightness(' + (1 - a / 90 * .5).toFixed(3) + ')';
    c.fb.style.transform = 'rotateX(90deg)';
  } else {
    c.ft.style.transform = 'rotateX(-90deg)';
    c.fb.style.transform = 'rotateX(' + (180 - a).toFixed(2) + 'deg)';
    c.fb.style.filter = 'brightness(' + (.5 + Math.min(1, (a - 90) / 90) * .5).toFixed(3) + ')';
  }
}

function frame(now) {
  if (!root.isConnected) { stop(); return; }
  raf = 0;
  const dt = Math.min(48, now - last); last = now;
  let busy = false;
  for (const c of cells) {
    if (c.t === 0) {
      if (c.cur === c.target) continue;
      busy = true;
      if (c.wait > 0) { c.wait -= dt; continue; }
      c.next = (c.cur + 1) % DRUM.length;
      c.last = c.next === c.target;
      c.dur = c.last ? 260 : 48 + Math.random() * 16;
      put(c.st, c.next); put(c.fbB, c.next);
      c.t = 0.0001;
    }
    busy = true;
    c.t += dt / c.dur;
    if (c.t >= 1) {
      c.cur = c.next;
      put(c.sb, c.cur); put(c.ftB, c.cur);
      c.t = 0;
      c.ft.style.transform = c.fb.style.transform = c.ft.style.filter = c.fb.style.filter = '';
      continue;
    }
    pose(c);
  }
  if (!busy) { settle(4600); return; }
  if (onScreen && !document.hidden) raf = requestAnimationFrame(frame);
}
function wake() {
  if (!raf && onScreen && !document.hidden) { last = performance.now(); raf = requestAnimationFrame(frame); }
}
function settle(ms) {
  clearTimeout(autoT);
  if (reduce) return;
  autoT = setTimeout(function auto() {
    if (!root.isConnected) { stop(); return; }
    if (!onScreen || document.hidden || hover || focusIn) { autoT = setTimeout(auto, 1500); return; }
    go(idx + 1);
  }, ms);
}

const io = new IntersectionObserver((es) => {
  onScreen = es[es.length - 1].isIntersecting;
  if (onScreen) wake();
});
io.observe(root);
const onVis = () => { if (!root.isConnected) { stop(); return; } if (!document.hidden) wake(); };
document.addEventListener('visibilitychange', onVis);
function stop() {
  cancelAnimationFrame(raf); raf = 0;
  clearTimeout(autoT);
  io.disconnect();
  document.removeEventListener('visibilitychange', onVis);
}

root.addEventListener('click', (e) => {
  const b = e.target.closest('.fxt-flap-btn');
  if (b) go(idx + +b.dataset.dir);
});
root.addEventListener('keydown', (e) => {
  const k = e.key;
  if (k === 'ArrowRight' || k === 'ArrowDown') go(idx + 1);
  else if (k === 'ArrowLeft' || k === 'ArrowUp') go(idx - 1);
  else if (k === 'Home') go(0);
  else if (k === 'End') go(DEPS.length - 1);
  else return;
  e.preventDefault();
});
root.addEventListener('pointerenter', () => { hover = true; });
root.addEventListener('pointerleave', () => { hover = false; });
root.addEventListener('focusin', () => { focusIn = true; });
root.addEventListener('focusout', (e) => { if (!root.contains(e.relatedTarget)) focusIn = false; });

setInstant(DEPS[0]);
info(DEPS[0], true);
settle(1800);

css:
@property --fxt-signal-sig {
  syntax: "<number>";
  inherits: true;
  initial-value: .64;
}
@property --fxt-signal-roll {
  syntax: "<percentage>";
  inherits: false;
  initial-value: -20%;
}
.fxt-signal {
  --fxt-signal-bg: oklch(0.175 0.014 140);
  --fxt-signal-ink: oklch(0.93 0.03 120);
  --fxt-signal-accent: oklch(0.87 0.19 126);
  --fxt-signal-live: oklch(0.66 0.23 27);
  --fxt-signal-dim: color-mix(in oklch, var(--fxt-signal-ink) 52%, var(--fxt-signal-bg));
  --fxt-signal-line: color-mix(in oklch, var(--fxt-signal-ink) 12%, transparent);
  container-type: inline-size;
  box-sizing: border-box;
  inline-size: 100%;
  display: grid;
  grid-template-areas: "bar" "screen" "ctl" "stats";
  gap: 11px;
  padding: 14px;
  border-radius: 14px;
  background: var(--fxt-signal-bg);
  color: var(--fxt-signal-ink);
  font-family: system-ui, sans-serif;
