const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const word = root.querySelector('.fxt-signal-word');
const screen = root.querySelector('.fxt-signal-screen');
const range = root.querySelector('.fxt-signal-range');
const out = root.querySelector('.fxt-signal-out');
const sub = root.querySelector('.fxt-signal-sub');
const snow = root.querySelector('.fxt-signal-snow');
const snrEl = root.querySelector('[data-k="snr"]');
const lossEl = root.querySelector('[data-k="loss"]');
const burstEl = root.querySelector('[data-k="burst"]');
const TEXT = word.dataset.text || word.textContent.trim();

// Seven horizontal slices, each a stack of R, G and B copies screened together:
// aligned they add to white, offset they fringe like a misconverged tube.
const S = 7, slices = [];
for (let k = 0; k < S; k++) {
  const sl = document.createElement('span');
  sl.className = 'fxt-signal-sl';
  sl.setAttribute('aria-hidden', 'true');
  for (const c of ['r', 'g', 'b']) {
    const ch = document.createElement('span');
    ch.className = 'fxt-signal-c';
    ch.dataset.c = c;
    ch.textContent = TEXT;
    sl.appendChild(ch);
  }
  word.appendChild(sl);
  slices.push({ el: sl, md: 0, gd: 0 });
}
const EVEN = Array.from({ length: S + 1 }, (_, k) => k / S);
let cuts = EVEN;
function setCuts(c) {
  cuts = c;
  slices.forEach((s, k) => {
    s.el.style.setProperty('--t', (c[k] * 100).toFixed(2) + '%');
    s.el.style.setProperty('--b', ((1 - c[k + 1]) * 100).toFixed(2) + '%');
  });
}
setCuts(EVEN);

const TIERS = [
  [85, 'ok', 'Broadcast nominal · next bulletin at 18:00'],
  [55, 'weak', 'Weather interference over Kettle Hill'],
  [25, 'poor', 'Signal degraded · retuning the mast'],
  [-1, 'lost', 'Carrier lost · scanning 470–862 MHz']
];
let sig = +range.value, burst = 0, bursts = 0, hold = 0, glitching = false, jump = 0;
let lossA = 0, totA = 1e-6, ha = 0, hoverOn = false, px = .5, py = .5, rect = null, ww = 300, tick = 0;

function readouts() {
  out.textContent = sig + '%';
  snrEl.textContent = (4 + .36 * sig).toFixed(1) + ' dB';
  const t = TIERS.find((x) => sig >= x[0]);
  if (root.dataset.tier !== t[1] || !sub.textContent) { root.dataset.tier = t[1]; sub.textContent = t[2]; }
  root.style.setProperty('--fxt-signal-sig', (sig / 100).toFixed(2));
}

const sctx = snow.getContext('2d');
let img = null, snowAcc = 1;
function snowSize(w, h) {
  if (!sctx) return;
  snow.width = 120;
  snow.height = Math.max(20, Math.round(120 * h / Math.max(1, w)));
  img = sctx.createImageData(snow.width, snow.height);
}
function snowStep(dt, level) {
  const op = Math.min(.5, level * level * .6);
  root.style.setProperty('--snow', op.toFixed(3));
  if (!img || op < .01) return;
  snowAcc += dt;
  if (snowAcc < .045) return;
  snowAcc = 0;
  const d = img.data, w = img.width;
  let tear = Math.random() < level * .6 ? (Math.random() * img.height) | 0 : -1;
  for (let i = 0, p = 0; i < d.length; i += 4, p++) {
    let v = Math.random() * 255;
    if (((p / w) | 0) === tear) v = 255;
    d[i] = d[i + 1] = d[i + 2] = v; d[i + 3] = 255;
  }
  sctx.putImageData(img, 0, 0);
}

function step(dt) {
  const noise = 1 - sig / 100;
  burst = Math.max(0, burst - dt * 1.5);
  const chaos = Math.min(1, Math.pow(noise, 1.4) * .9 + burst);
  hold -= dt;
  if (hold <= 0) {
    glitching = Math.random() < chaos * .45;
    if (glitching) {
      const c = [0];
      for (let k = 1; k < S; k++) c.push(Math.random());
      c.push(1);
      c.sort((a, b) => a - b);
      setCuts(c);
      slices.forEach((s) => { s.gd = Math.random() < .55 ? (Math.random() - .5) * ww * (.06 + chaos * .3) : 0; });
      jump = Math.random() < chaos * .22 ? (Math.random() - .5) * .22 : 0;
      hold = .035 + Math.random() * .11;
    } else {
      if (cuts !== EVEN) setCuts(EVEN);
      slices.forEach((s) => { s.gd = 0; });
      jump = 0;
      hold = .05 + Math.random() * (.55 - chaos * .45);
    }
  }
  // Pointer acts like a magnet held to the tube: nearby rows bend away from it.
  ha += ((hoverOn ? 1 : 0) - ha) * (1 - Math.exp(-dt * 8));
  let maxInf = 0;
  const a = 1 - Math.exp(-dt * 14);
  slices.forEach((s, k) => {
    const c = (cuts[k] + cuts[k + 1]) / 2;
    const inf = ha * Math.exp(-Math.pow((c - py) * 2.6, 2));
    if (inf > maxInf) maxInf = inf;
    s.md += (inf * (px - .5) * -.18 * ww - s.md) * a;
    s.el.style.setProperty('--dx', (s.md + s.gd).toFixed(1) + 'px');
  });
  const ca = noise * 2.2 + (glitching ? 2 + Math.random() * 9 * chaos : 0) + burst * 7 + maxInf * 6;
  word.style.setProperty('--ca', ca.toFixed(2) + 'px');
  word.style.setProperty('--jy', (jump * 100).toFixed(1) + '%');
  word.style.setProperty('--fl', glitching && chaos > .55 && Math.random() < .3 ? '.5' : '1');
  const dec = Math.exp(-dt / 4);
  lossA = lossA * dec + (glitching ? dt : 0);
  totA = totA * dec + dt;
  if ((tick++ & 7) === 0) lossEl.textContent = (lossA / totA * 100).toFixed(1) + '%';
  snowStep(dt, Math.min(1, noise + burst * .6));
}

let onScreen = false, raf = 0, last = 0, rmT = 0;
function frame(now) {
  if (!root.isConnected) { stop(); return; }
  raf = 0;
  const dt = Math.min(.05, (now - last) / 1000); last = now;
  step(dt);
  if (onScreen && !document.hidden) raf = requestAnimationFrame(frame);
}
function wake() {
  if (reduce) return;
  if (!raf && onScreen && !document.hidden) { last = performance.now(); raf = requestAnimationFrame(frame); }
}

function kick() {
  bursts++;
  burstEl.textContent = bursts;
  if (reduce) {
    // One still frame of misregistration, then back. No flicker.
    clearTimeout(rmT);
    word.style.setProperty('--ca', '5px');
    slices.forEach((s, k) => s.el.style.setProperty('--dx', (k % 2 ? 4 : -4) + 'px'));
    rmT = setTimeout(() => {
      if (!root.isConnected) return;
      word.style.removeProperty('--ca');
      slices.forEach((s) => s.el.style.removeProperty('--dx'));
    }, 420);
    return;
  }
  burst = 1;
  hold = 0;
  wake();
}
screen.addEventListener('pointerdown', kick);
screen.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); kick(); }
});
screen.addEventListener('pointerenter', () => { hoverOn = true; rect = word.getBoundingClientRect(); });
screen.addEventListener('pointermove', (e) => {
  if (!rect) rect = word.getBoundingClientRect();
  px = (e.clientX - rect.left) / Math.max(1, rect.width);
  py = (e.clientY - rect.top) / Math.max(1, rect.height);
  hoverOn = true;
});
screen.addEventListener('pointerleave', () => { hoverOn = false; rect = null; });
range.addEventListener('input', () => { sig = +range.value; readouts(); if (reduce) snowStep(1, 1 - sig / 100); });

const ro = new ResizeObserver(() => {
  ww = word.offsetWidth || ww;
  rect = null;
  snowSize(screen.clientWidth, screen.clientHeight);
  snowAcc = 1;
  snowStep(0, 1 - sig / 100);
});
ro.observe(screen);
const io = new IntersectionObserver((es) => {
  onScreen = es[es.length - 1].isIntersecting;
  if (onScreen) wake();
});
io.observe(root);
const onVis = () => { if (!root.isConnected) { stop(); return; } if (!document.hidden) wake(); };
document.addEventListener('visibilitychange', onVis);
function stop() {
  cancelAnimationFrame(raf); raf = 0;
  clearTimeout(rmT);
  io.disconnect(); ro.disconnect();
  document.removeEventListener('visibilitychange', onVis);
}

readouts();

