const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const STEPS = [
  { w: 'gathered', t: 1150, c: 'Molten glass is wound from the furnace onto a steel pipe.' },
  { w: 'blown', t: 1080, c: 'One long breath opens the gather into a thin-walled bubble.' },
