  container-type: inline-size;
  box-sizing: border-box;
  inline-size: 100%;
  display: grid;
  grid-template-areas: "head" "sheet" "foot";
  gap: 11px;
  padding: 14px;
  border-radius: 14px;
  background: var(--fxt-caret-bg);
  color: var(--fxt-caret-ink);
  font-family: system-ui, sans-serif;

  & .fxt-caret-head {
