  & .fxt-caret-doc svg {
    inline-size: 17px;
    block-size: 17px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.6;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxt-caret-mode {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 9px;
    border-radius: 99px;
    font-size: 10.5px;
    font-weight: 650;
    letter-spacing: .04em;
    white-space: nowrap;
    color: color-mix(in oklch, var(--fxt-caret-accent) 72%, var(--fxt-caret-ink));
