  }

  & .fxt-caret-sheet {
    grid-area: sheet;
    position: relative;
    border-radius: 10px;
    background: var(--fxt-caret-paper);
    box-shadow:
      inset 0 0 0 1px var(--fxt-caret-line),
      0 10px 24px -16px color-mix(in oklch, var(--fxt-caret-ink) 45%, transparent);
    transition: box-shadow .25s cubic-bezier(.2,.7,.2,1);
  }
  &:has(.fxt-caret-ed:focus) .fxt-caret-sheet {
    box-shadow:
      inset 0 0 0 1px color-mix(in oklch, var(--fxt-caret-accent) 55%, transparent),
      0 0 0 3px color-mix(in oklch, var(--fxt-caret-accent) 16%, transparent),
      0 10px 24px -16px color-mix(in oklch, var(--fxt-caret-ink) 45%, transparent);
  }
  & .fxt-caret-ed {
    min-block-size: calc(4lh + 32px);
    box-sizing: border-box;
    padding: 16px 18px;
    font-size: var(--fxt-caret-size);
    line-height: 1.55;
    letter-spacing: -.006em;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    outline: none;
    caret-color: transparent;
    cursor: text;
  }
  & .fxt-caret-ed::selection { background: color-mix(in oklch, var(--fxt-caret-accent) 22%, transparent); }
  & .fxt-caret-bar {
    position: absolute;
    left: 0;
    top: 0;
    inline-size: 2px;
    block-size: 1.22em;
    font-size: var(--fxt-caret-size);
    border-radius: 2px;
    background: var(--fxt-caret-accent);
    pointer-events: none;
    will-change: transform;
  }
  & .fxt-caret-trail {
    position: absolute;
    left: 0;
    top: 0;
    inline-size: 100px;
    block-size: .7em;
    font-size: var(--fxt-caret-size);
    border-radius: 99px;
    background: linear-gradient(90deg, transparent, color-mix(in oklch, var(--fxt-caret-accent) 50%, transparent));
    transform-origin: 0 0;
    opacity: 0;
    filter: blur(2.5px);
