    color: var(--fxt-caret-ink);
    font: 600 11.5px system-ui, sans-serif;
    cursor: pointer;
    transition: background-color .2s cubic-bezier(.2,.7,.2,1), translate .35s linear(0, 0.0471, 0.1663, 0.327, 0.5032, 0.675, 0.8281, 0.9541, 1.0493, 1.1136, 1.15, 1.1628, 1.1575, 1.1396, 1.1142, 1.0857, 1.0574, 1.0318, 1.0105, 0.9941, 0.9828, 0.9762, 0.9736, 0.974, 0.9767, 0.9807, 0.9853, 0.9899, 0.9942, 0.9978, 1.0006, 1.0026, 1.0037, 1.0043, 1.0043, 1.0039, 1.0033, 1.0025, 1.0018, 1.0011, 1);
  }
  & .fxt-caret-btn svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.8;
    stroke-linecap: round;
    stroke-linejoin: round;
    transition: rotate .7s linear(0, 0.0471, 0.1663, 0.327, 0.5032, 0.675, 0.8281, 0.9541, 1.0493, 1.1136, 1.15, 1.1628, 1.1575, 1.1396, 1.1142, 1.0857, 1.0574, 1.0318, 1.0105, 0.9941, 0.9828, 0.9762, 0.9736, 0.974, 0.9767, 0.9807, 0.9853, 0.9899, 0.9942, 0.9978, 1.0006, 1.0026, 1.0037, 1.0043, 1.0043, 1.0039, 1.0033, 1.0025, 1.0018, 1.0011, 1);
  }
  & .fxt-caret-btn:hover { background: color-mix(in oklch, var(--fxt-caret-accent) 8%, var(--fxt-caret-paper)); }
  & .fxt-caret-btn:hover svg { rotate: -320deg; }
  & .fxt-caret-btn:active { translate: 0 1px; }
  & .fxt-caret-btn:focus-visible { outline: 2px solid var(--fxt-caret-accent); outline-offset: 2px; }
}
.fxt-caret[data-idle] .fxt-caret-bar { animation: fxt-caret-blink 1.1s cubic-bezier(.45,0,.55,1) infinite; }
.fxt-caret[data-ranged] .fxt-caret-bar, .fxt-caret[data-ranged] .fxt-caret-trail { opacity: 0; }
.fxt-caret[data-mode="user"] .fxt-caret-mode { color: var(--fxt-caret-ink); background: color-mix(in oklch, var(--fxt-caret-ink) 8%, transparent); }
.fxt-caret[data-mode="paused"] .fxt-caret-mode { color: var(--fxt-caret-dim); background: color-mix(in oklch, var(--fxt-caret-ink) 6%, transparent); }
.fxt-caret:not([data-mode="auto"]) .fxt-caret-mode i { animation: none; }

@keyframes fxt-caret-blink {
