const doc = root.ownerDocument;
const ed = root.querySelector('.fxt-caret-ed');
const sheet = root.querySelector('.fxt-caret-sheet');
const bar = root.querySelector('.fxt-caret-bar');
const trail = root.querySelector('.fxt-caret-trail');
const modeT = root.querySelector('.fxt-caret-mode span');
const wEl = root.querySelector('[data-k="w"]');
const cEl = root.querySelector('[data-k="c"]');
const btn = root.querySelector('.fxt-caret-btn');
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
