  [['t', 'Marlow 2.4 syncs your notes in under a second'], ['w', 650], ['d', 18], ['t', ' before you finish the thought.'], ['w', 500],
   ['t', ' Offline edits now merge without conflicts, and search reads your handwriting.'], ['w', 2600], ['x']],
  [['t', 'Ilse, the prints arrive on Thursday'], ['w', 520], ['d', 8], ['t', 'Friday; the framer needs one more day.'], ['w', 450],
   ['t', ' I kept the oak, not the walnut, so the greens stay quiet.'], ['w', 2600], ['x']]
];
function finalText(d) {
