  for (const o of DRAFTS[d]) {
    if (o[0] === 't') s += o[1];
    else if (o[0] === 'd') s = s.slice(0, -o[1]);
    else if (o[0] === 'x') break;
  }
  return s;
}

let text = doc.createTextNode('');
