ed.appendChild(text);
// Open on a finished note so a still frame reads as a real document; the loop clears it first.
let draft = 1, op = DRAFTS[1].length - 2, ci = 0, typeT = 0;
text.data = finalText(1);

let x = 0, y = 0, vx = 0, vy = 0, gx = 0, gy = 0, gvx = 0, gvy = 0, tx = 0, ty = 0;
let barH = 24, idle = 0, dirty = true, snap = true, trailDir = '';
let onScreen = false, raf = 0, last = 0;
const KX = 820, CX = 2 * Math.sqrt(KX) * .5;
const KY = 1300, CY = 2 * Math.sqrt(KY) * .8;
const KG = 140, CG = 2 * Math.sqrt(KG) * .95;

function counts() {
  const s = ed.textContent;
  cEl.textContent = s.length;
  const t = s.trim();
  wEl.textContent = t ? t.split(/\s+/).length : 0;
}
function setMode(m) {
  root.dataset.mode = m;
  modeT.textContent = m === 'auto' ? (reduce ? 'Draft' : 'Autotyping') : m === 'user' ? 'Your turn' : 'Paused';
