  const sk = Math.max(-16, Math.min(16, -vx * .012));
  bar.style.transformOrigin = vx > 0 ? '100% 50%' : '0% 50%';
  bar.style.transform = 'translate(' + x.toFixed(2) + 'px,' + y.toFixed(2) + 'px) skewX(' + sk.toFixed(2) + 'deg) scale(' + sx.toFixed(3) + ',' + sy.toFixed(3) + ')';
  const dx = x - gx, ad = Math.abs(dx), dir = dx >= 0 ? 'r' : 'l';
  if (dir !== trailDir) { trailDir = dir; trail.dataset.dir = dir; }
