function frame(now) {
  if (!root.isConnected) { stop(); return; }
  raf = 0;
  const dt = Math.min(.034, (now - last) / 1000); last = now;
  if (dirty) { measure(); dirty = false; }
  if (snap || reduce) { x = gx = tx; y = gy = ty; vx = vy = gvx = gvy = 0; snap = false; }
