const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const stage = root.querySelector('.fxt-extrude-stage');
const word = root.querySelector('.fxt-extrude-word');
const range = root.querySelector('.fxt-extrude-range');
const outB = root.querySelector('.fxt-extrude-out b');
const btn = root.querySelector('.fxt-extrude-btn');
const TEXT = (word.dataset.word || word.textContent).trim();
const NL = 26;

// Each letter is a stack of 26 glyph slices pushed back in Z, plus a face.
// --fxt-extrude-d is a registered <length>, so depth changes interpolate
// through the stack with a spring curve instead of snapping.
word.textContent = '';
const letters = Array.from(TEXT).map((ch, i) => {
  const el = document.createElement('span');
  el.className = 'fxt-extrude-l';
  el.style.setProperty('--i', i);
  let h = '';
  for (let k = NL - 1; k >= 0; k--) h += '<i style="--k:' + (k / (NL - 1)).toFixed(3) + '">' + ch + '</i>';
  el.innerHTML = h + '<b>' + ch + '</b>';
  word.appendChild(el);
  return { el, ox: 0, w: 1, p: 0 };
});

let rx = 13, ry = -22, vrx = 0, vry = 0, tRx = 13, tRy = -22, ptr = false, manualUntil = 0, clock = 0;
let onScreen = false, raf = 0, last = 0, pt = 0;

function apply() {
  word.style.setProperty('--rx', rx.toFixed(2) + 'deg');
  word.style.setProperty('--ry', ry.toFixed(2) + 'deg');
  root.style.setProperty('--fxt-extrude-tilt', (ry / 40).toFixed(3));
}
function frame(now) {
  if (!root.isConnected) { stop(); return; }
  raf = 0;
  const dt = Math.min(.04, (now - last) / 1000); last = now;
  clock += dt;
  if (!ptr && now > manualUntil) {
    tRx = 13 + 6 * Math.sin(clock * .7);
    tRy = -16 + 18 * Math.sin(clock * .43);
  }
  const k = 70, c = 2 * Math.sqrt(k) * .6;
  vrx += (k * (tRx - rx) - c * vrx) * dt; rx += vrx * dt;
  vry += (k * (tRy - ry) - c * vry) * dt; ry += vry * dt;
  apply();
  if (onScreen && !document.hidden) raf = requestAnimationFrame(frame);
}
function wake() {
  if (reduce) return;
  if (!raf && onScreen && !document.hidden) { last = performance.now(); raf = requestAnimationFrame(frame); }
}

function measure() {
  const wl = word.offsetLeft;
  letters.forEach((L) => { L.w = L.el.offsetWidth || 1; L.ox = wl + L.el.offsetLeft + L.w / 2; });
}
function proximity(lx) {
  letters.forEach((L) => {
    const d = lx == null ? 9 : (lx - L.ox) / L.w;
    const p = Math.exp(-d * d * 1.1);
    if (Math.abs(p - L.p) > .02 || (p < .02 && L.p !== 0)) {
      L.p = p < .02 ? 0 : p;
      L.el.style.setProperty('--p', L.p.toFixed(2));
    }
  });
}
stage.addEventListener('pointermove', (e) => {
  if (reduce) return;
  const r = stage.getBoundingClientRect();
  const px = (e.clientX - r.left) / r.width, py = (e.clientY - r.top) / r.height;
  ptr = true;
  tRy = (px - .5) * 56;
  tRx = 10 - (py - .5) * 36;
  proximity(e.clientX - r.left);
});
stage.addEventListener('pointerleave', () => { ptr = false; proximity(null); });

function punch() {
  clearTimeout(pt);
  root.removeAttribute('data-release');
  root.setAttribute('data-punch', '');
  if (!reduce && stage.animate) {
    stage.animate([{ translate: '0 0' }, { translate: '0 4px' }, { translate: '0 -1px' }, { translate: '0 0' }],
      { duration: 300, delay: 130, easing: 'cubic-bezier(.3,.7,.4,1)' });
  }
  pt = setTimeout(() => {
    if (!root.isConnected) return;
    root.removeAttribute('data-punch');
    root.setAttribute('data-release', '');
    pt = setTimeout(() => { if (root.isConnected) root.removeAttribute('data-release'); }, 1500);
  }, 270);
}
stage.addEventListener('click', punch);
btn.addEventListener('click', punch);
stage.addEventListener('keydown', (e) => {
  const step = 7;
  switch (e.key) {
    case 'ArrowLeft': tRy -= step; break;
    case 'ArrowRight': tRy += step; break;
    case 'ArrowUp': tRx += step; break;
    case 'ArrowDown': tRx -= step; break;
    case 'Enter': case ' ': punch(); e.preventDefault(); return;
    case 'Escape': manualUntil = 0; e.preventDefault(); return;
    default: return;
  }
  e.preventDefault();
  tRx = Math.max(-35, Math.min(45, tRx));
  tRy = Math.max(-60, Math.min(60, tRy));
  manualUntil = performance.now() + 4000;
  if (reduce) { rx = tRx; ry = tRy; apply(); }
});
range.addEventListener('input', () => {
  root.style.setProperty('--fxt-extrude-base', range.value + 'px');
  outB.textContent = range.value;
});

const ro = new ResizeObserver(measure);
ro.observe(stage);
const io = new IntersectionObserver((es) => {
  onScreen = es[es.length - 1].isIntersecting;
  if (onScreen) wake();
});
io.observe(root);
const onVis = () => { if (!root.isConnected) { stop(); return; } if (!document.hidden) wake(); };
document.addEventListener('visibilitychange', onVis);
function stop() {
  cancelAnimationFrame(raf); raf = 0;
  clearTimeout(pt);
  io.disconnect(); ro.disconnect();
  document.removeEventListener('visibilitychange', onVis);
}

apply();
measure();

