.fxt-swarm {
  --fxt-swarm-bg: oklch(0.18 0.012 60);
  --fxt-swarm-ink: oklch(0.95 0.025 85);
  --fxt-swarm-hot: oklch(0.82 0.16 78);
  --fxt-swarm-ember: oklch(0.66 0.2 38);
  --fxt-swarm-dim: color-mix(in oklch, var(--fxt-swarm-ink) 50%, var(--fxt-swarm-bg));
  --fxt-swarm-line: color-mix(in oklch, var(--fxt-swarm-ink) 12%, transparent);
  container-type: inline-size;
  box-sizing: border-box;
  inline-size: 100%;
  display: grid;
  grid-template-areas: "top" "cv" "words";
  gap: 10px;
  padding: 14px;
  border-radius: 14px;
  background: var(--fxt-swarm-bg);
  color: var(--fxt-swarm-ink);
  font-family: system-ui, sans-serif;

  & .fxt-swarm-top {
    grid-area: top;
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 10px;
    font-size: 10px;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxt-swarm-dim);
  }
  & .fxt-swarm-top b { color: var(--fxt-swarm-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
  & .fxt-swarm-hint { letter-spacing: .08em; text-transform: none; font-style: italic; }
  & .fxt-swarm-cv {
    grid-area: cv;
    display: block;
    inline-size: 100%;
    block-size: clamp(140px, 48cqi, 270px);
    border-radius: 10px;
    background: var(--fxt-swarm-bg);
    box-shadow: inset 0 0 0 1px var(--fxt-swarm-line);
    touch-action: pan-y;
    cursor: pointer;
  }
  & .fxt-swarm-fallback {
    grid-area: cv;
    display: none;
    place-items: center;
    margin: 0;
    min-block-size: 140px;
    font: 900 clamp(40px, 16cqi, 96px)/1 system-ui, sans-serif;
    text-transform: uppercase;
    color: var(--fxt-swarm-ink);
  }
  & .fxt-swarm-words {
    grid-area: words;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 3px;
    padding: 3px;
    border-radius: 10px;
    background: color-mix(in oklch, var(--fxt-swarm-ink) 6%, transparent);
  }
  & .fxt-swarm-w {
    min-inline-size: 0;
    padding: 7px 2px;
    border: 0;
    border-radius: 8px;
    background: transparent;
    color: var(--fxt-swarm-dim);
    font: 700 10.5px system-ui, sans-serif;
    letter-spacing: .1em;
    text-transform: uppercase;
    cursor: pointer;
    transition: color .3s cubic-bezier(.2,.7,.2,1), background-color .3s cubic-bezier(.2,.7,.2,1), scale .3s cubic-bezier(.3,1.6,.5,1);
  }
  & .fxt-swarm-w:hover { color: var(--fxt-swarm-ink); }
  & .fxt-swarm-w:active { scale: .95; }
  & .fxt-swarm-w[aria-checked="true"] { color: var(--fxt-swarm-bg); background: var(--fxt-swarm-hot); }
  & .fxt-swarm-w:focus-visible { outline: 2px solid var(--fxt-swarm-hot); outline-offset: 2px; }
}
.fxt-swarm[data-static] .fxt-swarm-fallback { display: grid; }
.fxt-swarm[data-static] .fxt-swarm-cv { display: none; }

@container (max-width: 300px) {
  .fxt-swarm .fxt-swarm-w { letter-spacing: .03em; font-size: 10px; }
  .fxt-swarm .fxt-swarm-hint { display: none; }
}
@container (max-width: 250px) {
