.fxt-pluck {
  --fxt-pluck-bg: oklch(0.215 0.022 52);
  --fxt-pluck-ink: oklch(0.93 0.03 85);
  --fxt-pluck-wire: oklch(0.74 0.1 78);
  --fxt-pluck-accent: oklch(0.75 0.17 50);
  --fxt-pluck-dim: color-mix(in oklch, var(--fxt-pluck-ink) 50%, var(--fxt-pluck-bg));
  --fxt-pluck-line: color-mix(in oklch, var(--fxt-pluck-ink) 11%, transparent);
  container-type: inline-size;
  box-sizing: border-box;
  inline-size: 100%;
  display: grid;
  grid-template-areas: "head" "stage" "reads";
  gap: 6px;
  padding: 14px 14px 12px;
  border-radius: 14px;
  background:
    radial-gradient(90% 70% at 28% 18%, color-mix(in oklch, var(--fxt-pluck-wire) 13%, transparent), transparent 70%),
    repeating-linear-gradient(91deg, transparent 0 11px, color-mix(in oklch, black 7%, transparent) 11px 12px, transparent 12px 29px),
    var(--fxt-pluck-bg);
  color: var(--fxt-pluck-ink);
  font-family: system-ui, sans-serif;

  & .fxt-pluck-head {
    grid-area: head;
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 10px;
    font-size: 10px;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxt-pluck-dim);
  }
  & .fxt-pluck-head b { color: var(--fxt-pluck-ink); font-weight: 650; }
  & .fxt-pluck-hint { letter-spacing: .08em; text-transform: none; font-style: italic; }

  & .fxt-pluck-stage { grid-area: stage; position: relative; border-radius: 10px; outline: none; }
  & .fxt-pluck-stage:focus-visible { box-shadow: 0 0 0 2px color-mix(in oklch, var(--fxt-pluck-accent) 80%, transparent); }
  & .fxt-pluck-svg {
    display: block;
    inline-size: 100%;
    block-size: clamp(168px, 56cqi, 260px);
    overflow: visible;
    touch-action: none;
    cursor: crosshair;
  }
  & .fxt-pluck-stage[data-drag] .fxt-pluck-svg { cursor: grabbing; }

  & .fxt-pluck-s { --e: 0; }
  & .fxt-pluck-wire {
    fill: none;
    stroke: color-mix(in oklch, var(--fxt-pluck-accent) calc(var(--e) * 100%), var(--fxt-pluck-wire));
    stroke-width: calc(1.1px + var(--e) * 1.1px);
    stroke-linecap: round;
  }
  & .fxt-pluck-ghost {
    fill: none;
    stroke: var(--fxt-pluck-accent);
    stroke-width: 4px;
    stroke-linecap: round;
    opacity: calc(var(--e) * .32);
    filter: blur(2px);
  }
  & .fxt-pluck-peg { fill: var(--fxt-pluck-bg); stroke: var(--fxt-pluck-wire); stroke-width: 1.6px; }
  & .fxt-pluck-t {
    fill: color-mix(in oklch, var(--fxt-pluck-accent) calc(var(--e) * 72%), var(--fxt-pluck-ink));
    font-family: system-ui, sans-serif;
    letter-spacing: -.01em;
  }
  & .fxt-pluck-a .fxt-pluck-t { font-weight: 300; font-style: italic; }
  & .fxt-pluck-b .fxt-pluck-t { font-weight: 800; letter-spacing: -.035em; }
  & .fxt-pluck-c .fxt-pluck-t { font-weight: 500; }
  & .fxt-pluck-mark { fill: var(--fxt-pluck-accent); opacity: 0; transition: opacity .2s cubic-bezier(.2,.7,.2,1); }
  & .fxt-pluck-stage:focus-visible .fxt-pluck-s[data-sel] .fxt-pluck-mark { opacity: 1; }
  & .fxt-pluck-stage:focus-visible .fxt-pluck-s[data-sel] .fxt-pluck-peg { stroke: var(--fxt-pluck-accent); }

  & .fxt-pluck-reads {
    grid-area: reads;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
    padding-top: 9px;
    border-top: 1px solid var(--fxt-pluck-line);
  }
  & .fxt-pluck-r {
    --e: 0;
    display: grid;
    grid-template-columns: auto 1fr;
    grid-template-areas: "n hz" "m m";
    align-items: baseline;
    gap: 4px 6px;
    min-inline-size: 0;
  }
  & .fxt-pluck-r b {
    grid-area: n;
    font-size: 13px;
    font-weight: 700;
    color: color-mix(in oklch, var(--fxt-pluck-accent) calc(var(--e) * 100%), var(--fxt-pluck-ink));
  }
  & .fxt-pluck-r span {
    grid-area: hz;
    font: 500 10px ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxt-pluck-dim);
    white-space: nowrap;
  }
  & .fxt-pluck-m {
    grid-area: m;
    display: block;
    block-size: 3px;
    border-radius: 2px;
    background: var(--fxt-pluck-line);
    overflow: hidden;
  }
  & .fxt-pluck-m::after {
    content: "";
    display: block;
    block-size: 100%;
    background: var(--fxt-pluck-accent);
    transform-origin: 0 50%;
    transform: scaleX(var(--e));
  }
}

@container (max-width: 300px) {
  .fxt-pluck .fxt-pluck-hint { display: none; }
}
@container (max-width: 260px) {
  .fxt-pluck .fxt-pluck-r { grid-template-columns: 1fr; grid-template-areas: "n" "hz" "m"; }
}
@container (min-width: 560px) {
  .fxt-pluck .fxt-pluck-svg { block-size: clamp(200px, 40cqi, 320px); }
  .fxt-pluck .fxt-pluck-head { font-size: 11px; }
}

@media (prefers-reduced-motion: reduce) {
  .fxt-pluck .fxt-pluck-ghost { display: none; }
  .fxt-pluck .fxt-pluck-mark { transition: none; }
}

