const NS = 'http://www.w3.org/2000/svg';
const LINES = [
  { text: 'the quiet between notes', note: 'E2', hz: 82.41, cls: 'a', cap: 19 },
  { text: 'is where the song is kept', note: 'A2', hz: 110.0, cls: 'b', cap: 30 },
  { text: 'pull a line and let it ring', note: 'D3', hz: 146.83, cls: 'c', cap: 21 }
];
const N = 9, K = 64;
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const stage = root.querySelector('.fxt-pluck-stage');
const svg = root.querySelector('.fxt-pluck-svg');
const reads = root.querySelectorAll('.fxt-pluck-r');
const uid = 'fxt-pluck-' + Math.random().toString(36).slice(2, 8);
const mk = (tag, cls) => { const el = document.createElementNS(NS, tag); if (cls) el.setAttribute('class', cls); return el; };

// Mode shapes sin(n*pi*x/L), sampled once.
const SIN = [];
for (let n = 1; n <= N; n++) {
  const row = new Float32Array(K);
  for (let k = 0; k < K; k++) row[k] = Math.sin(n * Math.PI * k / (K - 1));
  SIN.push(row);
}
const Q = new Float32Array(N);
const measurer = mk('text');
measurer.setAttribute('visibility', 'hidden');
svg.appendChild(measurer);

let W = 300, H = 200, x0 = 14, x1 = 286;
const strings = LINES.map((L, i) => {
  const g = mk('g', 'fxt-pluck-s fxt-pluck-' + L.cls);
  const ghost = mk('path', 'fxt-pluck-ghost'), wire = mk('path', 'fxt-pluck-wire');
  wire.id = uid + '-' + i;
  const p0 = mk('circle', 'fxt-pluck-peg'), p1 = mk('circle', 'fxt-pluck-peg');
  p0.setAttribute('r', 3); p1.setAttribute('r', 3);
  const text = mk('text', 'fxt-pluck-t');
  text.setAttribute('text-anchor', 'middle');
  const tp = mk('textPath');
  tp.setAttribute('href', '#' + wire.id);
  tp.setAttributeNS('http://www.w3.org/1999/xlink', 'xlink:href', '#' + wire.id);
  tp.setAttribute('startOffset', '50%');
  tp.textContent = L.text;
  text.appendChild(tp);
  const mark = mk('path', 'fxt-pluck-mark');
  mark.setAttribute('d', 'M-5 8 5 8 0 2z');
  g.append(ghost, wire, p0, p1, text, mark);
  svg.appendChild(g);
  // Real pitch ratios, slowed to a visible fundamental; slight stiffness
  // inharmonicity (1 + B n^2) and higher modes dying faster, like a real string.
  const f1 = 2.3 * L.hz / 82.41;
  const w = new Float32Array(N), gam = new Float32Array(N);
  for (let n = 1; n <= N; n++) { w[n - 1] = 2 * Math.PI * f1 * n * (1 + .0025 * n * n); gam[n - 1] = .7 + .06 * n * n; }
  return { L, i, g, ghost, wire, p0, p1, text, mark, rest: 0, fs: 18, A: new Float32Array(N), ph: new Float32Array(N),
    w, gam, tau: 0, held: false, ys: new Float32Array(K), prev: '', e: -1, live: false };
});

function shape(s) {
  let amp = 0;
  for (let n = 0; n < N; n++) {
    let env, v;
    if (s.held) { env = v = s.A[n]; }
    else if (reduce) { env = v = s.A[n] * Math.exp(-7 * s.tau); }
    else { env = s.A[n] * Math.exp(-s.gam[n] * s.tau); v = env * Math.cos(s.w[n] * s.tau + s.ph[n]); }
    Q[n] = v;
    amp += env * env;
  }
  for (let k = 0; k < K; k++) {
    let y = 0;
    for (let n = 0; n < N; n++) y += Q[n] * SIN[n][k];
    s.ys[k] = s.rest + y;
  }
  return Math.sqrt(amp);
}
function pathD(s) {
  const dx = (x1 - x0) / (K - 1);
  let d = 'M' + x0.toFixed(1) + ' ' + s.ys[0].toFixed(2);
  for (let k = 1; k < K - 1; k++) {
    d += 'Q' + (x0 + k * dx).toFixed(1) + ' ' + s.ys[k].toFixed(2) + ' ' +
      (x0 + (k + .5) * dx).toFixed(1) + ' ' + ((s.ys[k] + s.ys[k + 1]) / 2).toFixed(2);
  }
  return d + 'L' + x1.toFixed(1) + ' ' + s.ys[K - 1].toFixed(2);
}
function render(s, amp) {
  const d = pathD(s);
  s.wire.setAttribute('d', d);
  s.ghost.setAttribute('d', s.prev || d);
  s.prev = d;
  const e = Math.min(1, amp / 15);
  if (Math.abs(e - s.e) > .004 || (e === 0 && s.e !== 0)) {
    s.e = e;
    const v = e.toFixed(3);
    s.g.style.setProperty('--e', v);
    reads[s.i].style.setProperty('--e', v);
  }
}

function layout() {
  const r = svg.getBoundingClientRect();
  if (r.width > 40) { W = r.width; H = r.height; }
  svg.setAttribute('viewBox', '0 0 ' + W.toFixed(1) + ' ' + H.toFixed(1));
  x0 = 14; x1 = W - 14;
  const span = x1 - x0;
  strings.forEach((s, i) => {
    s.rest = H * (i + .8) / 3;
    for (const p of [s.p0, s.p1]) p.setAttribute('cy', s.rest.toFixed(1));
    s.p0.setAttribute('cx', x0); s.p1.setAttribute('cx', x1.toFixed(1));
    const cs = getComputedStyle(s.text);
    measurer.style.fontWeight = cs.fontWeight;
    measurer.style.fontStyle = cs.fontStyle;
    measurer.style.letterSpacing = cs.letterSpacing;
    measurer.style.fontFamily = cs.fontFamily;
    measurer.style.fontSize = '20px';
    measurer.textContent = s.L.text;
    const len = measurer.getComputedTextLength() || s.L.text.length * 10;
    s.fs = Math.min(s.L.cap * Math.max(1, Math.min(1.6, W / 330)), 20 * span * .86 / len);
    s.text.style.fontSize = s.fs.toFixed(2) + 'px';
    s.prev = '';
    render(s, shape(s));
  });
  placeMark();
