.fxt-anagram {
  --fxt-anagram-bg: oklch(0.945 0.022 155);
  --fxt-anagram-tile: oklch(0.975 0.024 92);
  --fxt-anagram-ink: oklch(0.27 0.03 60);
  --fxt-anagram-accent: oklch(0.47 0.15 15);
  --fxt-anagram-edge: color-mix(in oklch, var(--fxt-anagram-tile) 70%, oklch(0.55 0.08 70));
  --fxt-anagram-dim: color-mix(in oklch, var(--fxt-anagram-ink) 56%, var(--fxt-anagram-bg));
  --fxt-anagram-line: color-mix(in oklch, var(--fxt-anagram-ink) 12%, transparent);
  --fxt-anagram-gap: 6px;
  container-type: inline-size;
  box-sizing: border-box;
  inline-size: 100%;
  display: grid;
  grid-template-areas: "top" "board" "def" "words" "foot";
  gap: 11px;
  padding: 14px;
  border-radius: 14px;
  background: var(--fxt-anagram-bg);
  color: var(--fxt-anagram-ink);
  font-family: system-ui, sans-serif;

  & .fxt-anagram-top {
    grid-area: top;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 8px;
  }
  & .fxt-anagram-title {
    font-size: 10px;
    font-weight: 700;
    letter-spacing: .16em;
    text-transform: uppercase;
    color: var(--fxt-anagram-dim);
  }
  & .fxt-anagram-sets {
    display: flex;
    gap: 2px;
    padding: 2px;
    border-radius: 8px;
    background: color-mix(in oklch, var(--fxt-anagram-ink) 7%, transparent);
  }
  & .fxt-anagram-tab {
    padding: 4px 7px;
    border: 0;
    border-radius: 6px;
    background: transparent;
    color: var(--fxt-anagram-dim);
    font: 600 10px ui-monospace, Menlo, monospace;
    letter-spacing: .06em;
    cursor: pointer;
    transition: background-color .25s cubic-bezier(.2,.7,.2,1), color .25s cubic-bezier(.2,.7,.2,1);
  }
  & .fxt-anagram-tab:hover { color: var(--fxt-anagram-ink); }
  & .fxt-anagram-tab[aria-selected="true"] {
    background: var(--fxt-anagram-tile);
    color: var(--fxt-anagram-ink);
    box-shadow: 0 1px 2px var(--fxt-anagram-line);
  }
  & .fxt-anagram-tab:focus-visible { outline: 2px solid var(--fxt-anagram-accent); outline-offset: 1px; }

  & .fxt-anagram-board {
    --ts: clamp(26px, calc((100cqi - 44px - 5 * var(--fxt-anagram-gap)) / 6.2), 58px);
    grid-area: board;
    position: relative;
    display: flex;
    justify-content: center;
    gap: var(--fxt-anagram-gap);
    padding: 22px 8px 24px;
    border-radius: 12px;
    background: color-mix(in oklch, var(--fxt-anagram-ink) 5%, transparent);
    box-shadow: inset 0 2px 6px color-mix(in oklch, var(--fxt-anagram-ink) 10%, transparent);
    cursor: pointer;
  }
  & .fxt-anagram-tile {
    position: relative;
    flex: none;
    inline-size: var(--ts);
    block-size: var(--ts);
    transition: opacity .45s cubic-bezier(.2,.7,.2,1), translate .8s linear(0, 0.0471, 0.1663, 0.327, 0.5032, 0.675, 0.8281, 0.9541, 1.0493, 1.1136, 1.15, 1.1628, 1.1575, 1.1396, 1.1142, 1.0857, 1.0574, 1.0318, 1.0105, 0.9941, 0.9828, 0.9762, 0.9736, 0.974, 0.9767, 0.9807, 0.9853, 0.9899, 0.9942, 0.9978, 1.0006, 1.0026, 1.0037, 1.0043, 1.0043, 1.0039, 1.0033, 1.0025, 1.0018, 1.0011, 1);
    transition-delay: calc(var(--i, 0) * 50ms + 120ms);
    @starting-style {
      opacity: 0;
      translate: 0 -24px;
    }
  }
  & .fxt-anagram-face {
    position: relative;
    display: grid;
    place-items: center;
    inline-size: 100%;
    block-size: 100%;
    border-radius: calc(var(--ts) * .16);
    background: linear-gradient(180deg, color-mix(in oklch, var(--fxt-anagram-tile), white 45%), var(--fxt-anagram-tile));
    box-shadow:
      0 calc(var(--ts) * .07) 0 var(--fxt-anagram-edge),
      0 calc(var(--ts) * .14) calc(var(--ts) * .22) -4px color-mix(in oklch, var(--fxt-anagram-ink) 35%, transparent);
    font-size: calc(var(--ts) * .54);
    font-weight: 750;
    line-height: 1;
    color: var(--fxt-anagram-ink);
    transition: translate .4s linear(0, 0.0471, 0.1663, 0.327, 0.5032, 0.675, 0.8281, 0.9541, 1.0493, 1.1136, 1.15, 1.1628, 1.1575, 1.1396, 1.1142, 1.0857, 1.0574, 1.0318, 1.0105, 0.9941, 0.9828, 0.9762, 0.9736, 0.974, 0.9767, 0.9807, 0.9853, 0.9899, 0.9942, 0.9978, 1.0006, 1.0026, 1.0037, 1.0043, 1.0043, 1.0039, 1.0033, 1.0025, 1.0018, 1.0011, 1);
  }
  & .fxt-anagram-face sub {
    position: absolute;
    right: 12%;
    bottom: 10%;
    font-size: calc(var(--ts) * .2);
    font-weight: 650;
    font-variant-numeric: tabular-nums;
    line-height: 1;
    color: var(--fxt-anagram-dim);
  }
  & .fxt-anagram-tile:hover .fxt-anagram-face { translate: 0 -5px; }

  & .fxt-anagram-def {
    grid-area: def;
    margin: 0;
    min-block-size: 2lh;
    font-size: 13px;
    line-height: 1.45;
    text-align: center;
    text-wrap: balance;
    color: color-mix(in oklch, var(--fxt-anagram-ink) 78%, var(--fxt-anagram-bg));
  }
  & .fxt-anagram-def b { margin-inline-end: .3em; font-weight: 700; font-style: italic; color: var(--fxt-anagram-accent); }

  & .fxt-anagram-words { grid-area: words; display: flex; flex-wrap: wrap; justify-content: center; gap: 5px; }
  & .fxt-anagram-chip {
    padding: 4px 10px;
    border: 1px solid var(--fxt-anagram-line);
    border-radius: 99px;
    background: transparent;
    color: var(--fxt-anagram-dim);
    font: 600 11px system-ui, sans-serif;
    letter-spacing: .02em;
    cursor: pointer;
    transition: background-color .25s cubic-bezier(.2,.7,.2,1), color .25s cubic-bezier(.2,.7,.2,1), border-color .25s cubic-bezier(.2,.7,.2,1), scale .3s linear(0, 0.0471, 0.1663, 0.327, 0.5032, 0.675, 0.8281, 0.9541, 1.0493, 1.1136, 1.15, 1.1628, 1.1575, 1.1396, 1.1142, 1.0857, 1.0574, 1.0318, 1.0105, 0.9941, 0.9828, 0.9762, 0.9736, 0.974, 0.9767, 0.9807, 0.9853, 0.9899, 0.9942, 0.9978, 1.0006, 1.0026, 1.0037, 1.0043, 1.0043, 1.0039, 1.0033, 1.0025, 1.0018, 1.0011, 1), opacity .4s cubic-bezier(.2,.7,.2,1);
    transition-delay: 0s, 0s, 0s, 0s, calc(var(--i, 0) * 40ms);
    @starting-style { opacity: 0; }
  }
  & .fxt-anagram-chip:hover { color: var(--fxt-anagram-ink); border-color: color-mix(in oklch, var(--fxt-anagram-ink) 30%, transparent); }
  & .fxt-anagram-chip:active { scale: .94; }
  & .fxt-anagram-chip[aria-checked="true"] {
    background: var(--fxt-anagram-accent);
    border-color: var(--fxt-anagram-accent);
    color: var(--fxt-anagram-tile);
  }
  & .fxt-anagram-chip:focus-visible { outline: 2px solid var(--fxt-anagram-accent); outline-offset: 2px; }

  & .fxt-anagram-foot {
    grid-area: foot;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 10px;
    padding-top: 10px;
    border-top: 1px solid var(--fxt-anagram-line);
    font-size: 11px;
    color: var(--fxt-anagram-dim);
  }
  & .fxt-anagram-foot b { color: var(--fxt-anagram-ink); font-weight: 700; font-variant-numeric: tabular-nums; }
  & .fxt-anagram-shuffle {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    flex: none;
    padding: 6px 11px 6px 9px;
    border: 0;
    border-radius: 8px;
    background: var(--fxt-anagram-ink);
    color: var(--fxt-anagram-tile);
    font: 650 11px system-ui, sans-serif;
    cursor: pointer;
    transition: translate .3s linear(0, 0.0471, 0.1663, 0.327, 0.5032, 0.675, 0.8281, 0.9541, 1.0493, 1.1136, 1.15, 1.1628, 1.1575, 1.1396, 1.1142, 1.0857, 1.0574, 1.0318, 1.0105, 0.9941, 0.9828, 0.9762, 0.9736, 0.974, 0.9767, 0.9807, 0.9853, 0.9899, 0.9942, 0.9978, 1.0006, 1.0026, 1.0037, 1.0043, 1.0043, 1.0039, 1.0033, 1.0025, 1.0018, 1.0011, 1), background-color .2s cubic-bezier(.2,.7,.2,1);
  }
  & .fxt-anagram-shuffle svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.8;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxt-anagram-shuffle:hover { background: var(--fxt-anagram-accent); }
  & .fxt-anagram-shuffle:active { translate: 0 1px; }
  & .fxt-anagram-shuffle:focus-visible { outline: 2px solid var(--fxt-anagram-accent); outline-offset: 2px; }
  &:has(.fxt-anagram-board:hover) .fxt-anagram-title { color: var(--fxt-anagram-accent); }
}

@container (max-width: 300px) {
  .fxt-anagram .fxt-anagram-title { display: none; }
  .fxt-anagram .fxt-anagram-top { justify-content: center; }
}
@container (max-width: 250px) {
  .fxt-anagram { --fxt-anagram-gap: 4px; }
  .fxt-anagram .fxt-anagram-board { padding-inline: 4px; }
  .fxt-anagram .fxt-anagram-every { display: none; }
}
@container (min-width: 560px) {
  .fxt-anagram .fxt-anagram-def { font-size: 14.5px; }
  .fxt-anagram .fxt-anagram-board { padding-block: 30px 32px; }
}

@media (prefers-reduced-motion: reduce) {
  .fxt-anagram .fxt-anagram-tile, .fxt-anagram .fxt-anagram-chip { transition: none; }
  .fxt-anagram .fxt-anagram-face, .fxt-anagram .fxt-anagram-tab, .fxt-anagram .fxt-anagram-shuffle { transition: none; }
  .fxt-anagram .fxt-anagram-tile:hover .fxt-anagram-face { translate: none; }
}

