const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const SETS = [
  [['listen', 'to give your attention to a sound'], ['silent', 'making no sound at all'], ['enlist', 'to sign up to serve or to help'],
   ['tinsel', 'thin glittering strips hung as decoration'], ['inlets', 'narrow arms of water reaching inland']],
  [['caret', 'the mark showing where text will be inserted'], ['react', 'to respond to something that happens'], ['trace', 'to follow a line and copy its path'],
   ['crate', 'a slatted wooden box for shipping goods'], ['cater', 'to provide food and drink for guests']],
  [['staple', 'a basic item you use every day'], ['pastel', 'a soft, pale shade of a colour'], ['petals', 'the coloured leaves that ring a flower'],
   ['plates', 'flat dishes for serving food'], ['palest', 'the most pale of them all']]
