const VAL = { a: 1, c: 3, e: 1, i: 1, l: 1, n: 1, p: 3, r: 1, s: 1, t: 1 };
const board = root.querySelector('.fxt-anagram-board');
const tabs = Array.from(root.querySelectorAll('.fxt-anagram-tab'));
const wordsBox = root.querySelector('.fxt-anagram-words');
const def = root.querySelector('.fxt-anagram-def');
const defW = def.querySelector('b'), defT = def.querySelector('span');
const nEl = root.querySelector('[data-k="n"]'), ptsEl = root.querySelector('[data-k="pts"]');
const shuffleBtn = root.querySelector('.fxt-anagram-shuffle');
let set = 0, wi = 0, tiles = [], chips = [], autoT = 0, hover = false, focusIn = false, onScreen = false;

function makeTile(ch, i) {
  const t = document.createElement('span');
  t.className = 'fxt-anagram-tile';
  t.dataset.ch = ch;
  t.style.setProperty('--i', i);
  t.style.order = i;
  t.innerHTML = '<span class="fxt-anagram-face">' + ch.toUpperCase() + '<sub>' + VAL[ch] + '</sub></span>';
