  }
}

function buildSet(s, animate) {
  if (animate && !reduce && tiles.length) {
    const pos = tiles.map((t) => [t.offsetLeft, t.offsetTop]);
    tiles.forEach((t, i) => {
      t.style.position = 'absolute';
      t.style.left = pos[i][0] + 'px';
      t.style.top = pos[i][1] + 'px';
      t.style.transition = 'none';
      const a = t.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateY(26px) rotate(' + (i % 2 ? 9 : -9) + 'deg)' }],
