  tiles.forEach((t) => board.appendChild(t));
  wordsBox.textContent = '';
  chips = SETS[s].map(([w], i) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'fxt-anagram-chip';
    b.setAttribute('role', 'radio');
    b.style.setProperty('--i', i);
    b.textContent = w;
    b.addEventListener('click', () => { show(i); schedule(6000); });
    wordsBox.appendChild(b);
    return b;
  });
