    t.animate([{ translate: dx + 'px ' + dy + 'px' }, { translate: '0 0' }], { duration: dur, easing: 'cubic-bezier(.62,0,.24,1)' });
    t.animate([
      { transform: 'translateY(0) rotate(0deg)', easing: 'cubic-bezier(.22,.62,.36,1)' },
      { transform: 'translateY(' + lift.toFixed(1) + 'px) rotate(' + (right ? 7 : -5) + 'deg)', easing: 'cubic-bezier(.64,0,.78,.38)' },
      { transform: 'translateY(0) rotate(0deg)' }
    ], { duration: dur });
    t.firstChild.animate([{ scale: '1' }, { scale: '1', offset: .84 }, { scale: '1.1 .86', offset: .92 }, { scale: '1' }],
      { duration: dur + 160, easing: 'cubic-bezier(.3,.7,.4,1)' });
  });
}

function next() {
  if (wi + 1 >= SETS[set].length) buildSet((set + 1) % SETS.length, true);
  else show(wi + 1);
}
function schedule(ms) {
  clearTimeout(autoT);
  if (reduce) return;
  autoT = setTimeout(function tick() {
    if (!root.isConnected) { io.disconnect(); return; }
    if (!onScreen || document.hidden || hover || focusIn) { autoT = setTimeout(tick, 1200); return; }
    next();
    schedule(wi === 0 ? 3600 : 2700);
  }, ms);
}

tabs.forEach((t, i) => t.addEventListener('click', () => { if (i !== set) buildSet(i, true); schedule(6000); }));
root.querySelector('.fxt-anagram-sets').addEventListener('keydown', (e) => {
  const k = tabs.indexOf(e.target);
  if (k < 0) return;
  let n;
  if (e.key === 'ArrowRight') n = (k + 1) % tabs.length;
  else if (e.key === 'ArrowLeft') n = (k - 1 + tabs.length) % tabs.length;
  else if (e.key === 'Home') n = 0;
  else if (e.key === 'End') n = tabs.length - 1;
  else return;
  e.preventDefault();
  tabs[n].focus();
  buildSet(n, true);
  schedule(6000);
});
wordsBox.addEventListener('keydown', (e) => {
  let n;
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') n = wi + 1;
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') n = wi - 1;
  else return;
  e.preventDefault();
  show(n);
  chips[wi].focus();
  schedule(6000);
});
shuffleBtn.addEventListener('click', () => { show(wi + 1); schedule(6000); });
board.addEventListener('click', () => { show(wi + 1); schedule(6000); });
root.addEventListener('pointerenter', () => { hover = true; });
root.addEventListener('pointerleave', () => { hover = false; });
root.addEventListener('focusin', () => { focusIn = true; });
root.addEventListener('focusout', (e) => { if (!root.contains(e.relatedTarget)) focusIn = false; });

const io = new IntersectionObserver((es) => { onScreen = es[es.length - 1].isIntersecting; });
io.observe(root);

buildSet(0, false);
schedule(2400);
